import json
HEAD="Fixed camera, the flat gray background stays exactly the same color and brightness the whole time, no camera movement, no zoom. "
def tail(col, idle=False):
    fx=("No magic effects and no glow appear. " if idle else
        f"Rich, clearly visible {col} effects, medium brightness, in both the effect and the glow on the body. ")
    return ("No arc-shaped or crescent light trails, no sweeping slashes, no circles or rings anywhere, nothing glows on the ground. "+fx+
     "All moves are smooth and continuous, no sudden jumps, no flicker. The body stays solid and fully visible in every moment: never fades, never turns transparent or ghostly, no smoke or haze rectangle, no explosion filling the frame. "
     "No white-out, no lens flare, no starburst, no star-shaped or cross-shaped glint, no burst of rays, no full-frame flash, no smoke filling the frame; nothing flies in from the edges; "
     "nothing is aimed or thrown to the left or to the right; effects stay close to the body and never touch the left and right edges of the frame. The end pose equals the start pose.")
def body(desc, pron, planted=True):
    spot="feet planted on the same spot" if planted else "stays on the same spot"
    return f"{desc} keeps the same size, {spot}, and faces the viewer the whole time, chest toward the viewer; never turns the back or the side to the viewer. "
